const out = [];
let seq = 0;

for (const item of $input.all()) {
  const patients = Array.isArray(item.json.patients) ? item.json.patients : [];
  for (const p of patients) {
    const blob = JSON.stringify(p).toLowerCase();

    // Detect NDIS plan management type from any text field on the patient
    let planType = '';
    if (blob.includes('plan-managed') || blob.includes('plan managed')) planType = 'plan';
    else if (blob.includes('self-managed') || blob.includes('self managed')) planType = 'self';
    else if (blob.includes('ndia')) planType = 'agency';

    // Patients with no NDIS marker are not NDIS participants - skip them
    if (!planType) continue;

    // Plan manager email if one is present anywhere on the record
    const pmMatch = blob.match(/planmanager[0-9]+@[a-z0-9.-]+/);
    const pmEmail = pmMatch ? pmMatch[0] : '';

    // Synthetic NDIS number for test records: 43 + last 7 digits of the reference number
    seq++;
    const digits = String(p.reference_number ?? '').replace(/[^0-9]/g, '');
    const tail = (digits || String(seq)).slice(-7).padStart(7, '0');

    out.push({ json: {
      patient_id: String(p.id),
      first_name: p.first_name || '',
      last_name: p.last_name || '',
      ndis_number: '43' + tail,
      plan_type: planType,
      plan_start: '2026-01-01',
      plan_end: '2027-12-31',
      plan_manager_email: pmEmail,
      participant_email: p.email || ''
    }});
  }
}
return out;
